# region: emit
def emit(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(intake(fold(sift(render(emit(raw))))))

